int32_t _json_valid_utf8(PenguString s) {

const unsigned char *p = (const unsigned char *)(s.data ? s.data : "");
int i = 0;
while (i < s.len) {
    unsigned c = p[i];
    if (c < 0x80u) { i++; continue; }
    int len; unsigned cp;
    if ((c & 0xE0u) == 0xC0u) { len = 2; cp = c & 0x1Fu; }
    else if ((c & 0xF0u) == 0xE0u) { len = 3; cp = c & 0x0Fu; }
    else if ((c & 0xF8u) == 0xF0u) { len = 4; cp = c & 0x07u; }
    else { return i; }
    if (i + len > s.len) { return i; }
    for (int k = 1; k < len; k++) {
        unsigned cc = p[i + k];
        if ((cc & 0xC0u) != 0x80u) { return i + k; }
        cp = (cp << 6) | (cc & 0x3Fu);
    }
    if (len == 2 && cp < 0x80u) { return i; }
    if (len == 3 && cp < 0x800u) { return i; }
    if (len == 4 && cp < 0x10000u) { return i; }
    if (cp > 0x10FFFFu) { return i; }
    if (cp >= 0xD800u && cp <= 0xDFFFu) { return i; }
    i += len;
}
return -1;
}
bool _json_strtoll(PenguString s, int32_t start, int32_t end, int64_t* out) {

if (start < 0 || end < start || end > s.len) return false;
char *endp = NULL;
errno = 0;
long long v = strtoll(s.data + start, &endp, 10);
if (errno == ERANGE || endp != s.data + end) return false;
*out = (int64_t)v;
return true;
}
bool _json_strtod(PenguString s, int32_t start, int32_t end, double* out) {

if (start < 0 || end < start || end > s.len) return false;
char *endp = NULL;
errno = 0;
double v = strtod(s.data + start, &endp);
if (endp != s.data + end) return false;
if (errno == ERANGE && (v == 0.0 || v == HUGE_VAL || v == -HUGE_VAL)) return false;
*out = (double)v;
return true;
}
PenguString _json_format_f64(double f) {

char buf[64];
if (isnan(f)) return pengu_string_new("NaN");
if (isinf(f)) return f < 0 ? pengu_string_new("-Infinity") : pengu_string_new("Infinity");
if (f == 0.0) {
    return signbit(f) ? pengu_string_new("-0.0") : pengu_string_new("0.0");
}
int p;
for (p = 1; p <= 17; p++) {
    snprintf(buf, sizeof buf, "%.*g", p, f);
    if (strtod(buf, NULL) == f) break;
}
if (p > 17) p = 17;
snprintf(buf, sizeof buf, "%.*e", p - 1, f);
const char *q = buf;
char sign = 0;
if (*q == '-') { sign = '-'; q++; }
char digits[32];
int nd = 0;
while (*q && *q != 'e' && *q != 'E') {
    if (*q >= '0' && *q <= '9' && nd < 31) digits[nd++] = *q;
    q++;
}
if (*q == 'e' || *q == 'E') q++;
int exp10 = atoi(q);
while (nd > 1 && digits[nd - 1] == '0') nd--;

char out[96];
int k = 0;
if (sign) out[k++] = '-';
if (exp10 >= -4 && exp10 < 16) {
    if (exp10 >= 0) {
        int int_digits = exp10 + 1;
        if (nd <= int_digits) {
            for (int i = 0; i < nd; i++) out[k++] = digits[i];
            for (int i = nd; i < int_digits; i++) out[k++] = '0';
            out[k++] = '.';
            out[k++] = '0';
        } else {
            for (int i = 0; i < int_digits; i++) out[k++] = digits[i];
            out[k++] = '.';
            for (int i = int_digits; i < nd; i++) out[k++] = digits[i];
        }
    } else {
        out[k++] = '0';
        out[k++] = '.';
        for (int i = 0; i < -exp10 - 1; i++) out[k++] = '0';
        for (int i = 0; i < nd; i++) out[k++] = digits[i];
    }
} else {
    out[k++] = digits[0];
    if (nd > 1) {
        out[k++] = '.';
        for (int i = 1; i < nd; i++) out[k++] = digits[i];
    }
    out[k++] = 'e';
    if (exp10 < 0) { out[k++] = '-'; exp10 = -exp10; }
    else out[k++] = '+';
    char ebuf[16];
    snprintf(ebuf, sizeof ebuf, "%02d", exp10);
    for (const char *e = ebuf; *e; e++) out[k++] = *e;
}
out[k] = '\0';
return pengu_string_new(out);
}
JsonValue _json_clone_value(JsonValue v) {

JsonValue out;
memset(&out, 0, sizeof out);
out.tag = v.tag;
switch (v.tag) {
case JsonValue_Null:
    break;
case JsonValue_Bool:
    out.data.Bool.value = v.data.Bool.value;
    break;
case JsonValue_Int:
    out.data.Int.value = v.data.Int.value;
    break;
case JsonValue_Float:
    out.data.Float.value = v.data.Float.value;
    break;
case JsonValue_Str:
    out.data.Str.value = pengu_string_owned(
        v.data.Str.value.data ? v.data.Str.value.data : "", v.data.Str.value.len);
    break;
case JsonValue_Arr: {
    int n = v.data.Arr.items.len;
    out.data.Arr.items = pengu_list_new(sizeof(JsonValue), n);
    for (int i = 0; i < n; i++) {
        JsonValue el = *(JsonValue *)pengu_list_at(&v.data.Arr.items, i);
        JsonValue copy = _json_clone_value(el);
        pengu_list_push(&out.data.Arr.items, &copy);
    }
    break;
}
case JsonValue_Obj: {
    int n = v.data.Obj.entries.len;
    out.data.Obj.entries = pengu_list_new(sizeof(JsonEntry), n);
    for (int i = 0; i < n; i++) {
        JsonEntry *e = (JsonEntry *)pengu_list_at(&v.data.Obj.entries, i);
        JsonEntry copy;
        copy.key = pengu_string_owned(e->key.data ? e->key.data : "", e->key.len);
        copy.value = _json_clone_value(e->value);
        pengu_list_push(&out.data.Obj.entries, &copy);
    }
    break;
}
}
return out;
}
void _json_free_raw(JsonValue* v) {

if (!v) return;
switch (v->tag) {
case JsonValue_Str:
    pengu_banish_string(&v->data.Str.value);
    break;
case JsonValue_Arr: {
    int n = v->data.Arr.items.len;
    for (int i = 0; i < n; i++) {
        _json_free_raw((JsonValue *)pengu_list_at(&v->data.Arr.items, i));
    }
    pengu_banish_list(&v->data.Arr.items);
    break;
}
case JsonValue_Obj: {
    int n = v->data.Obj.entries.len;
    for (int i = 0; i < n; i++) {
        JsonEntry *e = (JsonEntry *)pengu_list_at(&v->data.Obj.entries, i);
        pengu_banish_string(&e->key);
        _json_free_raw(&e->value);
    }
    pengu_banish_list(&v->data.Obj.entries);
    break;
}
default:
    break;
}
memset(v, 0, sizeof *v);
}
void _json_obj_put(PenguList* entries, PenguString key, JsonValue value) {

PenguList *l = entries;
JsonEntry *es = (JsonEntry *)l->data;
for (int i = 0; i < l->len; i++) {
    if (pengu_string_equal(es[i].key, key)) {
        _pengu_cleanup_JsonValue(&es[i].value);
        es[i].value = value;
        pengu_banish_string(&key);
        return;
    }
}
JsonEntry e;
e.key = key;
e.value = value;
pengu_list_push(l, &e);
}
