int32_t psc_os_proc_exec_replace(PenguList argv) {

#if defined(_WIN32)
if (argv.len <= 0)
return -1;
char **v = (char **)malloc(((size_t)argv.len + 1) * sizeof(char *));
if (!v)
return -1;
for (int i = 0; i < argv.len; i++)
{
PenguString *s = (PenguString *)pengu_list_at(&argv, i);
v[i] = (s && s->data) ? s->data : (char *)"";
}
v[argv.len] = NULL;
int rc = _spawnvp(_P_WAIT, v[0], (const char *const *)v);
free(v);
return rc;
#else
extern int execvp(const char *, char *const[]);
if (argv.len <= 0)
return 127;
char **v = (char **)malloc(((size_t)argv.len + 1) * sizeof(char *));
if (!v)
return 127;
for (int i = 0; i < argv.len; i++)
{
PenguString *s = (PenguString *)pengu_list_at(&argv, i);
v[i] = (s && s->data) ? s->data : (char *)"";
}
v[argv.len] = NULL;
execvp(v[0], v);
free(v);
return 127;
#endif
}
int32_t psc_os_proc_run_argv(PenguList argv) {

#if defined(_WIN32)
if (argv.len <= 0)
return -1;
char **v = (char **)malloc(((size_t)argv.len + 1) * sizeof(char *));
if (!v)
return -1;
for (int i = 0; i < argv.len; i++)
{
PenguString *s = (PenguString *)pengu_list_at(&argv, i);
v[i] = (s && s->data) ? s->data : (char *)"";
}
v[argv.len] = NULL;
int rc = _spawnvp(_P_WAIT, v[0], (const char *const *)v);
free(v);
return rc;
#else
extern int fork(void);
extern int waitpid(int, int *, int);
extern int execvp(const char *, char *const[]);
extern void _exit(int);
#define PSC_WIFEXITED(st) (((st) & 0x7f) == 0)
#define PSC_WEXITSTATUS(st) (((st) & 0xff00) >> 8)
#define PSC_WIFSIGNALED(st) ((((st) & 0x7f) != 0) && (((st) & 0x7f) != 0x7f))
#define PSC_WTERMSIG(st) ((st) & 0x7f)
if (argv.len <= 0)
return -1;
char **v = (char **)malloc(((size_t)argv.len + 1) * sizeof(char *));
if (!v)
return -1;
for (int i = 0; i < argv.len; i++)
{
PenguString *s = (PenguString *)pengu_list_at(&argv, i);
v[i] = (s && s->data) ? s->data : (char *)"";
}
v[argv.len] = NULL;
int pid = fork();
if (pid < 0)
{
free(v);
return -1;
}
if (pid == 0)
{
execvp(v[0], v);
_exit(127);
}
int st = 0;
while (waitpid(pid, &st, 0) < 0)
{
if (errno != EINTR)
{
free(v);
return -1;
}
}
free(v);
if (PSC_WIFEXITED(st))
return PSC_WEXITSTATUS(st);
if (PSC_WIFSIGNALED(st))
return 128 + PSC_WTERMSIG(st);
return -1;
#endif
}
int32_t psc_os_proc_spawn_argv(PenguList argv) {

#if defined(_WIN32)
(void)argv;
return 0;
#else
extern int fork(void);
extern int execvp(const char *, char *const[]);
extern void _exit(int);
if (argv.len <= 0) return 0;
char **v = (char **)malloc(((size_t)argv.len + 1) * sizeof(char *));
if (!v) return 0;
for (int i = 0; i < argv.len; i++) {
    PenguString *s = (PenguString *)pengu_list_at(&argv, i);
    v[i] = (s && s->data) ? s->data : (char *)"";
}
v[argv.len] = NULL;
int pid = fork();
if (pid < 0) { free(v); return 0; }
if (pid == 0) { execvp(v[0], v); _exit(127); }
free(v);
return pid;
#endif
}
int32_t psc_os_proc_wait_pid(int32_t pid) {

#if defined(_WIN32)
(void)pid;
return -1;
#else
extern int waitpid(int, int *, int);
#define PSC_WIFEXITED2(st) (((st) & 0x7f) == 0)
#define PSC_WEXITSTATUS2(st) (((st) & 0xff00) >> 8)
int st = 0;
while (waitpid(pid, &st, 0) < 0) return -1;
if (PSC_WIFEXITED2(st)) return PSC_WEXITSTATUS2(st);
return -1;
#endif
}
bool psc_os_proc_pid_alive(int32_t pid) {

#if defined(_WIN32)
(void)pid;
return false;
#else
extern int waitpid(int, int *, int);
int st = 0;
int r = waitpid(pid, &st, 1);
return r == 0;
#endif
}
