int64_t _net_listen(PenguString host, int32_t port) {

#if defined(_WIN32)
(void)host; (void)port;
return -1;
#else
char portbuf[16];
snprintf(portbuf, sizeof(portbuf), "%d", port);
char *hostbuf = (char *)malloc((size_t)host.len + 1);
if (!hostbuf)
return -1;
memcpy(hostbuf, host.data ? host.data : "", (size_t)host.len);
hostbuf[host.len] = '\0';
struct addrinfo hints;
struct addrinfo *res = NULL;
memset(&hints, 0, sizeof(hints));
hints.ai_family = AF_UNSPEC;
hints.ai_socktype = SOCK_STREAM;
hints.ai_flags = AI_PASSIVE;
int gai = getaddrinfo((host.len > 0) ? hostbuf : NULL, portbuf, &hints, &res);
free(hostbuf);
if (gai != 0)
return -1;
int64_t result = -1;
for (struct addrinfo *rp = res; rp != NULL; rp = rp->ai_next)
{
int fd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
if (fd < 0)
continue;
int one = 1;
setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));
if (bind(fd, rp->ai_addr, rp->ai_addrlen) == 0 && listen(fd, 16) == 0)
{
result = (int64_t)fd;
break;
}
close(fd);
}
freeaddrinfo(res);
return result;
#endif
}
int64_t _net_accept(int64_t fd) {

#if defined(_WIN32)
(void)fd;
return -1;
#else
if (fd < 0)
return -1;
int c = accept((int)fd, NULL, NULL);
if (c < 0)
return -(int64_t)errno;
return (int64_t)c;
#endif
}
PenguMaybe _net_read_exact(int64_t fd, int32_t n) {

#if defined(_WIN32)
(void)fd; (void)n;
return pengu_maybe_none();
#else
if (fd < 0 || n <= 0)
return pengu_maybe_none();
sds buf = sdsnewlen(NULL, (size_t)n);
if (!buf)
return pengu_maybe_none();
size_t got = 0;
while (got < (size_t)n)
{
ssize_t part = recv((int)fd, buf + got, (size_t)n - got, 0);
if (part < 0 && errno == EINTR)
continue;
if (part <= 0)
{
sdsfree(buf);
return pengu_maybe_none();
}
got += (size_t)part;
}
PenguString *boxed = (PenguString *)malloc(sizeof(PenguString));
if (!boxed)
{
sdsfree(buf);
return pengu_maybe_none();
}
*boxed = pengu_string_owned_from_sds_len(buf, n);
return pengu_maybe_some(boxed);
#endif
}
int32_t _net_write(int64_t fd, PenguString data) {

#if defined(_WIN32)
(void)fd; (void)data;
return -1;
#else
if (fd < 0 || !data.data || data.len <= 0)
return 0;
size_t sent = 0;
while (sent < (size_t)data.len)
{
ssize_t part = send((int)fd, data.data + sent, (size_t)data.len - sent, 0);
if (part < 0 && errno == EINTR)
continue;
if (part <= 0)
return -((int)errno);
sent += (size_t)part;
}
return (int)sent;
#endif
}
void _net_close(int64_t fd) {

#if defined(_WIN32)
(void)fd;
#else
if (fd >= 0)
close((int)fd);
#endif
}
